def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)

    # A diagonal pair starts a ray from the end pointing away from the
    # other colored cells in the motif.
    for r in range(h - 1):
        for c in range(w - 1):
            for dr, dc in ((1, 1), (1, -1)):
                r2, c2 = r + dr, c + dc
                color = grid[r][c]
                if color == bg or grid[r2][c2] != color:
                    continue

                ends = [
                    (r - dr, c - dc, -dr, -dc),
                    (r2 + dr, c2 + dc, dr, dc),
                ]
                valid = []
                for rr, cc, vr, vc in ends:
                    if 0 <= rr < h and 0 <= cc < w:
                        valid.append((grid[rr][cc] == bg, rr, cc, vr, vc))
                    else:
                        valid.append((True, rr, cc, vr, vc))

                # Prefer the end whose next cell is empty/background.
                _, rr, cc, vr, vc = max(valid, key=lambda x: x[0])
                while 0 <= rr < h and 0 <= cc < w:
                    if grid[rr][cc] != bg:
                        break
                    out[rr][cc] = color
                    rr += vr
                    cc += vc

    return out
